-- VIOLATION: comma-separated tags in one column
CREATE TABLE posts_bad (
  id    INTEGER PRIMARY KEY,
  title TEXT,
  tags  TEXT  -- 'postgresql,database,sql' — wrong!
);
-- Problem: cannot query by tag, cannot count tags, ordering is ambiguous

-- FIXED: separate tags table with a junction table
CREATE TABLE tags (
  id   BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);
CREATE TABLE post_tags (
  post_id BIGINT REFERENCES posts(id) ON DELETE CASCADE,
  tag_id  BIGINT REFERENCES tags(id)  ON DELETE CASCADE,
  PRIMARY KEY (post_id, tag_id)
);

-- VIOLATION: repeating groups
CREATE TABLE orders_bad (
  id       INTEGER PRIMARY KEY,
  product1 TEXT,
  qty1     INTEGER,
  product2 TEXT,   -- repeating group — wrong!
  qty2     INTEGER
);

-- posts.comment_count is denormalized for fast display
-- Instead of: SELECT COUNT(*) FROM comments WHERE post_id = 1 (on every page load)
-- Store it: posts.comment_count INTEGER DEFAULT 0

-- Maintain with a trigger:
CREATE OR REPLACE FUNCTION update_comment_count()
RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE posts SET comment_count = comment_count + 1 WHERE id = NEW.post_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE posts SET comment_count = comment_count - 1 WHERE id = OLD.post_id;
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_comment_count
AFTER INSERT OR DELETE ON comments
FOR EACH ROW EXECUTE FUNCTION update_comment_count();
